import 'package:flutter/material.dart';class WeeklyTipsCard extends StatelessWidget{final String title;final List<String> tips;final Color accentColor;const WeeklyTipsCard({super.key,required this.title,required this.tips,this.accentColor=const Color(0xFFE91E63)});@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:TextStyle(fontSize:17,fontWeight:FontWeight.w800,color:accentColor)),const SizedBox(height:8),...tips.map((t)=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.check_circle_outline,color:accentColor,size:19),const SizedBox(width:8),Expanded(child:Text(t))]))) ])));}}
